import hashlib,json
from cryptography.hazmat.primitives import hashes,serialization
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.exceptions import InvalidSignature

def p256(pem):
    key=serialization.load_pem_public_key(pem.encode())
    if not isinstance(key,ec.EllipticCurvePublicKey) or not isinstance(key.curve,ec.SECP256R1):raise ValueError("ES256 P-256 only")
    return key

def unique_object(pairs):
    result={}
    for key,value in pairs:
        if key in result:raise ValueError("duplicate JSON key")
        result[key]=value
    return result

def verify_assertion(connection,credential_id,client_data,auth_data,signature,now):
    try:data=json.loads(client_data.decode("utf8"),object_pairs_hook=unique_object)
    except (ValueError,UnicodeError) as exc:raise ValueError("invalid client data") from exc
    if not isinstance(data,dict) or data.get("type")!="webauthn.get" or data.get("origin")!="https://opsforge.example" or data.get("crossOrigin",False) is not False or "topOrigin" in data:raise ValueError("client context rejected")
    if len(auth_data)!=37 or auth_data[:32]!=hashlib.sha256(b"opsforge.example").digest():raise ValueError("RP or data layout rejected")
    flags=auth_data[32]
    if flags&5!=5 or flags&0xe2 or flags&16 and not flags&8:raise ValueError("UP/UV or flags rejected")
    counter=int.from_bytes(auth_data[33:37],"big")
    with connection:
        connection.execute("BEGIN IMMEDIATE")
        challenge=connection.execute("SELECT subject,expires,consumed FROM challenges WHERE value=?",(data.get("challenge"),)).fetchone()
        credential=connection.execute("SELECT subject,pem,counter,revoked FROM credentials WHERE id=?",(credential_id,)).fetchone()
        if not challenge or not credential or challenge[1]<=now or challenge[2] or credential[3] or credential[0]!=challenge[0]:raise ValueError("credential or challenge rejected")
        subject=credential[0]
        if connection.execute("SELECT enabled FROM subjects WHERE subject=?",(subject,)).fetchone()!=(1,):raise ValueError("disabled subject")
        try:p256(credential[1]).verify(signature,auth_data+hashlib.sha256(client_data).digest(),ec.ECDSA(hashes.SHA256()))
        except (InvalidSignature,TypeError) as exc:raise ValueError("signature rejected") from exc
        if (counter or credential[2]) and counter<=credential[2]:raise ValueError("counter risk rejected by this RP policy")
        connection.execute("UPDATE credentials SET counter=? WHERE id=?",(counter,credential_id))
        connection.execute("UPDATE challenges SET consumed=1 WHERE value=?",(data["challenge"],))
    return subject

def recover(connection,recovery_id,new_id,new_pem,now):
    p256(new_pem)
    with connection:
        connection.execute("BEGIN IMMEDIATE")
        ticket=connection.execute("SELECT subject,expires,consumed FROM recoveries WHERE id=?",(recovery_id,)).fetchone()
        if not ticket or ticket[1]<=now or ticket[2]:raise ValueError("recovery unavailable")
        subject=ticket[0]
        if connection.execute("SELECT enabled FROM subjects WHERE subject=?",(subject,)).fetchone()!=(1,):raise ValueError("disabled subject")
        reviewers={r[0] for r in connection.execute("SELECT a.actor FROM approvals a JOIN reviewers r ON r.actor=a.actor WHERE a.recovery_id=? AND r.enabled=1 AND a.actor!=?",(recovery_id,subject))}
        if len(reviewers)<2:raise ValueError("two independent approved reviewers required")
        if not new_id or connection.execute("SELECT 1 FROM credentials WHERE id=?",(new_id,)).fetchone():raise ValueError("new credential identity required")
        connection.execute("UPDATE credentials SET revoked=1 WHERE subject=?",(subject,))
        connection.execute("INSERT INTO credentials(id,subject,pem,counter,revoked) VALUES(?,?,?,0,0)",(new_id,subject,new_pem))
        connection.execute("UPDATE recoveries SET consumed=1 WHERE id=?",(recovery_id,))
    return subject
